//! [`open_enum!`](macro@crate::open_enum): the one shape of every enum Meta may
//! extend.
//!
//! Meta adds values to its enums without notice (a template status, a
//! restriction type, a quality score). A closed `#[derive(Deserialize)]`
//! enum turns such a value into a parse failure of the whole answer or
//! webhook; a unit `#[serde(other)] Unknown` keeps parsing but drops the
//! value, and writes its own name back where Meta's was. So every open enum
//! of `meta-whatsapp-rs` is generated by this macro (roadmap L20a): the
//! values the docs list become variants, and any other value lands in
//! `Other(String)` **verbatim**, so it round-trips unchanged through
//! deserialize and serialize, and shows in logs.
//!
//! A value Meta documents as `UNKNOWN` (or `OTHER`) is a variant like any
//! other, spelled as the docs spell it; it is never the catch-all. Where a
//! documented `OTHER` would collide with the catch-all, the variant is
//! named after what it is (`FlowCategory::OtherCategory`,
//! `Vertical::OtherVertical`).
//!
//! What a generated enum has:
//!
//! - `#[derive(Debug, Clone, PartialEq, Eq, Hash)]` and
//!   `#[non_exhaustive]` (Meta adds values: naming one is not a breaking
//!   change); attributes written above the enum are kept, so it may derive
//!   more (`PartialOrd`, `Ord`);
//! - `as_str()`, the value as Meta spells it (a variant's first spelling,
//!   or `Other`'s value), and `Display`, the same;
//! - `From<&str>`, `From<String>` and `FromStr` (`Err = Infallible`):
//!   a listed spelling gives its variant, anything else `Other`, verbatim
//!   (build values this way, so a listed value never ends up in `Other`);
//! - `Serialize` (as `as_str()`) and `Deserialize`. A string parses as
//!   `From<&str>`; any other JSON value (Meta's examples sometimes print a
//!   number where the prose says string) is kept as its JSON text in
//!   `Other`, so the enum never fails a response or a webhook. Such a
//!   value serializes back as a string.
//!
//! The grammar, options first, in any order:
//!
//! ```text
//! open_enum! {
//!     #![case_insensitive]          // listed spellings match in any ASCII case
//!     #![normalize = path::to::fn]  // fn(&str) -> impl AsRef<str>, applied before matching
//!     #![string_only]               // a JSON value that is not a string fails to deserialize
//!     /// Docs.
//!     pub enum Name {
//!         /// Docs.
//!         Variant => "WIRE" | "ALIAS",   // aliases: other spellings Meta's pages use
//!     }
//! }
//! ```
//!
//! - `case_insensitive` is for the enums Meta prints in different cases on
//!   different pages (`"marketing"` in one template example, `"MARKETING"`
//!   in the next); the first spelling is still what serializes.
//! - `normalize` rewrites the value only to compare it (for example spaces
//!   into underscores, where Meta's pages spell one value both ways); a
//!   value that matches nothing is still kept as it came.
//! - `string_only` is for documents this crate also writes and reads back
//!   whole (Flow JSON): there a value of the wrong JSON type must fail, so
//!   the document around it is kept raw rather than rewritten as a string.
//!
//! ```
//! meta_whatsapp_core::open_enum! {
//!     /// A status.
//!     pub enum Status {
//!         /// `ACTIVE`.
//!         Active => "ACTIVE",
//!     }
//! }
//!
//! let known: Status = serde_json::from_str(r#""ACTIVE""#).unwrap();
//! assert_eq!(known, Status::Active);
//! let new: Status = serde_json::from_str(r#""ARCHIVED""#).unwrap();
//! assert_eq!(new, Status::Other("ARCHIVED".to_owned()));
//! assert_eq!(serde_json::to_string(&new).unwrap(), r#""ARCHIVED""#);
//! ```
//!
//! Outside the crate that declares it, a `match` on a generated enum
//! needs a wildcard arm, even one naming `Other`:
//!
//! ```compile_fail,E0004
//! use meta_whatsapp_core::store::WindowEventKind;
//!
//! fn name(kind: &WindowEventKind) -> &str {
//!     match kind {
//!         WindowEventKind::CustomerCall => "call",
//!         WindowEventKind::CallAccepted => "accepted",
//!         WindowEventKind::StandbyMessage => "standby",
//!         WindowEventKind::Other(name) => name,
//!     }
//! }
//! ```
//!
//! ```
//! use meta_whatsapp_core::store::WindowEventKind;
//!
//! fn name(kind: &WindowEventKind) -> &str {
//!     match kind {
//!         WindowEventKind::CustomerCall => "call",
//!         WindowEventKind::CallAccepted => "accepted",
//!         WindowEventKind::StandbyMessage => "standby",
//!         WindowEventKind::Other(name) => name,
//!         _ => "a value this revision names",
//!     }
//! }
//! assert_eq!(name(&WindowEventKind::from("customer_call")), "call");
//! ```

use std::fmt;
use std::marker::PhantomData;

use serde::de::{self, Deserializer, MapAccess, SeqAccess, Visitor};

/// Generate an open string enum: documented values as variants, any other
/// value kept verbatim in `Other(String)`. See the
/// [module docs](mod@crate::open_enum) for what it generates and its options.
#[macro_export]
macro_rules! open_enum {
    // Options: inner attributes before the enum, in any order, accumulated
    // as `[case_insensitive?] [normalize path?] [string_only?]`.
    (@opts [$($ci:ident)?] [$($norm:path)?] [$($so:ident)?] #![case_insensitive] $($rest:tt)*) => {
        $crate::open_enum!(@opts [case_insensitive] [$($norm)?] [$($so)?] $($rest)*);
    };
    (@opts [$($ci:ident)?] [$($norm:path)?] [$($so:ident)?] #![normalize = $n:path] $($rest:tt)*) => {
        $crate::open_enum!(@opts [$($ci)?] [$n] [$($so)?] $($rest)*);
    };
    (@opts [$($ci:ident)?] [$($norm:path)?] [$($so:ident)?] #![string_only] $($rest:tt)*) => {
        $crate::open_enum!(@opts [$($ci)?] [$($norm)?] [string_only] $($rest)*);
    };
    (@opts [$($ci:ident)?] [$($norm:path)?] [$($so:ident)?]
        $(#[$meta:meta])*
        $vis:vis enum $name:ident {
            $(
                $(#[$vmeta:meta])*
                $variant:ident => $wire:literal $(| $alias:literal)*
            ),+ $(,)?
        }
    ) => {
        $(#[$meta])*
        #[derive(Debug, Clone, PartialEq, Eq, Hash)]
        #[non_exhaustive]
        $vis enum $name {
            $(
                $(#[$vmeta])*
                $variant,
            )+
            /// A value the docs this crate was written against do not
            /// list, kept verbatim: it serializes back unchanged. Build
            /// values with `From<&str>` (or `parse`), so that a listed
            /// value maps to its variant rather than to `Other`.
            Other(::std::string::String),
        }

        #[allow(deprecated)]
        impl $name {
            /// The value as Meta spells it.
            pub fn as_str(&self) -> &str {
                match self {
                    $( Self::$variant => $wire, )+
                    Self::Other(value) => value.as_str(),
                }
            }
        }

        #[allow(deprecated)]
        impl ::core::convert::From<&str> for $name {
            fn from(value: &str) -> Self {
                let key: &str = value;
                $(
                    let normalized = $norm(key);
                    let key: &str = ::core::convert::AsRef::<str>::as_ref(&normalized);
                )?
                let found: ::core::option::Option<Self> = $crate::open_enum!(
                    @lookup [$($ci)?] key, $( $variant => $wire $(| $alias)* ),+
                );
                match found {
                    ::core::option::Option::Some(known) => known,
                    ::core::option::Option::None => Self::Other(value.to_owned()),
                }
            }
        }

        impl ::core::convert::From<::std::string::String> for $name {
            fn from(value: ::std::string::String) -> Self {
                match Self::from(value.as_str()) {
                    Self::Other(_) => Self::Other(value),
                    known => known,
                }
            }
        }

        impl ::core::str::FromStr for $name {
            type Err = ::core::convert::Infallible;

            /// Never fails: a value not listed becomes `Other`.
            fn from_str(value: &str) -> ::core::result::Result<Self, Self::Err> {
                ::core::result::Result::Ok(Self::from(value))
            }
        }

        impl ::core::fmt::Display for $name {
            fn fmt(&self, f: &mut ::core::fmt::Formatter<'_>) -> ::core::fmt::Result {
                f.write_str(self.as_str())
            }
        }

        impl $crate::__private::serde::Serialize for $name {
            fn serialize<S: $crate::__private::serde::Serializer>(
                &self,
                serializer: S,
            ) -> ::core::result::Result<S::Ok, S::Error> {
                serializer.serialize_str(self.as_str())
            }
        }

        impl<'de> $crate::__private::serde::Deserialize<'de> for $name {
            fn deserialize<D: $crate::__private::serde::Deserializer<'de>>(
                deserializer: D,
            ) -> ::core::result::Result<Self, D::Error> {
                $crate::open_enum!(@deserialize [$($so)?] deserializer)
            }
        }
    };
    (@deserialize [] $deserializer:ident) => {
        $crate::open_enum::deserialize($deserializer)
    };
    (@deserialize [string_only] $deserializer:ident) => {
        $crate::open_enum::deserialize_string($deserializer)
    };
    (@lookup [] $key:ident, $( $variant:ident => $wire:literal $(| $alias:literal)* ),+) => {
        match $key {
            $( $wire $(| $alias)* => ::core::option::Option::Some(Self::$variant), )+
            _ => ::core::option::Option::None,
        }
    };
    (@lookup [case_insensitive] $key:ident, $( $variant:ident => $wire:literal $(| $alias:literal)* ),+) => {
        match $crate::open_enum!(@lookup [] $key, $( $variant => $wire $(| $alias)* ),+) {
            ::core::option::Option::Some(known) => ::core::option::Option::Some(known),
            ::core::option::Option::None => {
                $(
                    if $key.eq_ignore_ascii_case($wire) $(|| $key.eq_ignore_ascii_case($alias))* {
                        ::core::option::Option::Some(Self::$variant)
                    } else
                )+
                {
                    ::core::option::Option::None
                }
            }
        }
    };
    (@opts $($rest:tt)*) => {
        ::core::compile_error!(
            "open_enum!: expected options (`#![case_insensitive]`, `#![normalize = path]`, `#![string_only]`), then one enum whose variants read `Variant => \"wire\" | \"alias\"`"
        );
    };
    ($($input:tt)*) => {
        $crate::open_enum!(@opts [] [] [] $($input)*);
    };
}

/// Deserialize a `#![string_only]` open enum: a string through
/// `From<&str>`/`From<String>`; any other value fails, as a derived
/// `Deserialize` of a string would. Used by
/// [`open_enum!`](macro@crate::open_enum).
///
/// # Errors
///
/// A value that is not a string, and the deserializer's own.
#[doc(hidden)]
pub fn deserialize_string<'de, D, T>(deserializer: D) -> Result<T, D::Error>
where
    D: Deserializer<'de>,
    T: for<'a> From<&'a str> + From<String>,
{
    deserializer.deserialize_str(StringVisitor(PhantomData))
}

struct StringVisitor<T>(PhantomData<T>);

impl<T> Visitor<'_> for StringVisitor<T>
where
    T: for<'a> From<&'a str> + From<String>,
{
    type Value = T;

    fn expecting(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("a string")
    }

    fn visit_str<E: de::Error>(self, value: &str) -> Result<T, E> {
        Ok(T::from(value))
    }

    fn visit_string<E: de::Error>(self, value: String) -> Result<T, E> {
        Ok(T::from(value))
    }
}

/// Deserialize an open enum from any value: a string through
/// `From<&str>`/`From<String>`, anything else as its JSON text (through
/// `From<String>`, so into `Other`). Used by [`open_enum!`](macro@crate::open_enum).
///
/// # Errors
///
/// Only the deserializer's own (malformed input).
#[doc(hidden)]
pub fn deserialize<'de, D, T>(deserializer: D) -> Result<T, D::Error>
where
    D: Deserializer<'de>,
    T: for<'a> From<&'a str> + From<String>,
{
    deserializer.deserialize_any(OpenVisitor(PhantomData))
}

struct OpenVisitor<T>(PhantomData<T>);

impl<'de, T> Visitor<'de> for OpenVisitor<T>
where
    T: for<'a> From<&'a str> + From<String>,
{
    type Value = T;

    fn expecting(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("a string (any other value is kept as its JSON text)")
    }

    fn visit_str<E: de::Error>(self, value: &str) -> Result<T, E> {
        Ok(T::from(value))
    }

    fn visit_string<E: de::Error>(self, value: String) -> Result<T, E> {
        Ok(T::from(value))
    }

    fn visit_bool<E: de::Error>(self, value: bool) -> Result<T, E> {
        Ok(T::from(value.to_string()))
    }

    fn visit_i64<E: de::Error>(self, value: i64) -> Result<T, E> {
        Ok(T::from(value.to_string()))
    }

    fn visit_u64<E: de::Error>(self, value: u64) -> Result<T, E> {
        Ok(T::from(value.to_string()))
    }

    fn visit_f64<E: de::Error>(self, value: f64) -> Result<T, E> {
        Ok(T::from(serde_json::Value::from(value).to_string()))
    }

    fn visit_unit<E: de::Error>(self) -> Result<T, E> {
        Ok(T::from(String::from("null")))
    }

    fn visit_none<E: de::Error>(self) -> Result<T, E> {
        self.visit_unit()
    }

    fn visit_some<D: Deserializer<'de>>(self, deserializer: D) -> Result<T, D::Error> {
        deserializer.deserialize_any(self)
    }

    fn visit_seq<A: SeqAccess<'de>>(self, seq: A) -> Result<T, A::Error> {
        let value: serde_json::Value =
            serde::Deserialize::deserialize(de::value::SeqAccessDeserializer::new(seq))?;
        Ok(T::from(value.to_string()))
    }

    fn visit_map<A: MapAccess<'de>>(self, map: A) -> Result<T, A::Error> {
        let value: serde_json::Value =
            serde::Deserialize::deserialize(de::value::MapAccessDeserializer::new(map))?;
        Ok(T::from(value.to_string()))
    }
}

#[cfg(test)]
mod tests {
    use std::collections::HashMap;

    use pretty_assertions::assert_eq;

    crate::open_enum! {
        /// Test enum.
        pub enum Sample {
            /// A.
            A => "a",
            /// B, spelled two ways.
            B => "b-b" | "b_b",
            /// Documented as `UNKNOWN`: a value, not the catch-all.
            Unknown => "UNKNOWN",
            /// Deprecated: still spelled.
            #[deprecated(note = "test")]
            Old => "old",
        }
    }

    crate::open_enum! {
        #![case_insensitive]
        /// Case-insensitive test enum.
        pub enum Loose {
            /// `MARKETING`.
            Marketing => "MARKETING",
            /// `en_US`, also spelled `en-US`.
            EnUs => "en_US" | "en-US",
        }
    }

    fn spaces(value: &str) -> String {
        value.trim().replace(' ', "_")
    }

    crate::open_enum! {
        #![normalize = spaces]
        #![case_insensitive]
        /// Normalized test enum.
        pub enum Spaced {
            /// `Needs_Testing`.
            NeedsTesting => "Needs_Testing",
        }
    }

    crate::open_enum! {
        #![string_only]
        /// String-only test enum.
        pub enum Strict {
            /// `a`.
            A => "a",
        }
    }

    fn parse<T: serde::de::DeserializeOwned>(json: &str) -> T {
        serde_json::from_str(json).unwrap()
    }

    #[test]
    fn string_only_refuses_another_json_type_and_keeps_unknown_strings() {
        assert_eq!(parse::<Strict>(r#""a""#), Strict::A);
        assert_eq!(parse::<Strict>(r#""zzz""#), Strict::Other("zzz".into()));
        for json in ["42", "true", "null", "[]", "{}"] {
            assert!(serde_json::from_str::<Strict>(json).is_err(), "{json}");
        }
        assert_eq!(parse::<Option<Strict>>("null"), None);
        // An owned string (`visit_string`, as from a `serde_json::Value`).
        let owned = |v: serde_json::Value| serde_json::from_value::<Strict>(v).unwrap();
        assert_eq!(owned(serde_json::json!("a")), Strict::A);
        assert_eq!(owned(serde_json::json!("zzz")), Strict::Other("zzz".into()));
        assert!(serde_json::from_value::<Strict>(serde_json::json!(42)).is_err());
    }

    #[test]
    fn an_owned_string_parses_as_a_borrowed_one() {
        // `serde_json::from_value` hands the visitor an owned `String`.
        let owned = |v: serde_json::Value| serde_json::from_value::<Sample>(v).unwrap();
        assert_eq!(owned(serde_json::json!("b_b")), Sample::B);
        assert_eq!(owned(serde_json::json!("zzz")), Sample::Other("zzz".into()));
        assert_eq!(owned(serde_json::json!(42)), Sample::Other("42".into()));
        assert_eq!(
            owned(serde_json::json!({"a": [1]})),
            Sample::Other(r#"{"a":[1]}"#.into())
        );
    }

    #[test]
    fn listed_values_and_aliases_parse_to_their_variant() {
        assert_eq!(parse::<Sample>(r#""a""#), Sample::A);
        assert_eq!(parse::<Sample>(r#""b_b""#), Sample::B);
        assert_eq!(parse::<Sample>(r#""b-b""#), Sample::B);
        assert_eq!(parse::<Sample>(r#""UNKNOWN""#), Sample::Unknown);
        #[allow(deprecated)]
        let old = Sample::Old;
        assert_eq!(parse::<Sample>(r#""old""#), old);
        assert_eq!(serde_json::to_string(&Sample::B).unwrap(), r#""b-b""#);
        assert_eq!(Sample::from(String::from("a")), Sample::A);
        assert_eq!("a".parse::<Sample>(), Ok(Sample::A));
        // Exact unless asked otherwise.
        assert_eq!(Sample::from("A"), Sample::Other("A".into()));
    }

    #[test]
    fn an_unknown_value_round_trips_unchanged() {
        for raw in [
            "zzz",
            "A_VALUE_NO_PAGE_LISTS",
            "",
            " a ",
            "Unknown",
            "Other",
        ] {
            let json = serde_json::to_string(raw).unwrap();
            let value: Sample = parse(&json);
            assert_eq!(value, Sample::Other(raw.into()), "{raw:?}");
            assert_eq!(serde_json::to_string(&value).unwrap(), json);
            assert_eq!(value.as_str(), raw);
            assert_eq!(value.to_string(), raw);
            assert_eq!(Sample::from(raw), value);
            assert_eq!(Sample::from(raw.to_owned()), value);
        }
    }

    #[test]
    fn a_non_string_value_is_kept_as_its_json_text() {
        for json in ["42", "-1", "1.5", "true", "null", "[1,\"x\"]", r#"{"a":1}"#] {
            assert_eq!(parse::<Sample>(json), Sample::Other(json.into()), "{json}");
        }
        // Inside an `Option`, `null` is still `None`.
        assert_eq!(parse::<Option<Sample>>("null"), None);
        assert_eq!(parse::<Option<Sample>>(r#""a""#), Some(Sample::A));
    }

    #[test]
    fn case_insensitive_matches_any_case_and_keeps_unknowns_verbatim() {
        assert_eq!(parse::<Loose>(r#""marketing""#), Loose::Marketing);
        assert_eq!(parse::<Loose>(r#""EN_us""#), Loose::EnUs);
        // An alias matches in any case too, and serializes as the first.
        assert_eq!(parse::<Loose>(r#""EN-us""#), Loose::EnUs);
        assert_eq!(Loose::from("En-Us").as_str(), "en_US");
        assert_eq!(Loose::from("en_US").as_str(), "en_US");
        assert_eq!(Loose::from("Promo"), Loose::Other("Promo".into()));
        assert_eq!(
            serde_json::to_string(&Loose::from("marketing")).unwrap(),
            r#""MARKETING""#
        );
    }

    #[test]
    fn normalize_applies_before_matching_and_never_to_other() {
        assert_eq!(Spaced::from("Needs Testing"), Spaced::NeedsTesting);
        assert_eq!(Spaced::from(" needs_testing "), Spaced::NeedsTesting);
        assert_eq!(
            Spaced::from(" New value "),
            Spaced::Other(" New value ".into())
        );
        assert_eq!(Spaced::NeedsTesting.as_str(), "Needs_Testing");
    }

    #[test]
    fn works_as_a_map_key() {
        let map: HashMap<Sample, u8> = parse(r#"{"a": 1, "new": 2}"#);
        assert_eq!(map[&Sample::A], 1);
        assert_eq!(map[&Sample::Other("new".into())], 2);
        assert_eq!(
            serde_json::to_value(&map).unwrap(),
            serde_json::json!({"a": 1, "new": 2})
        );
    }
}
